#include <bits/stdc++.h>

#define For(i, l, r) for (register int i = (l), i##end = (int)(r); i <= i##end; ++i)
#define Fordown(i, r, l) for (register int i = (r), i##end = (int)(l); i >= i##end; --i)
#define Rep(i, r) for (register int i = (0), i##end = (int)(r); i < i##end; ++i)
#define Set(a, v) memset(a, v, sizeof(a))
#define Cpy(a, b) memcpy(a, b, sizeof(a))
#define debug(x) cout << #x << ": " << (x) << endl
#define pb push_back

using namespace std;

typedef long long ll;

template<typename T> inline bool chkmin(T &a, T b) { return b < a ? a = b, 1 : 0; }
template<typename T> inline bool chkmax(T &a, T b) { return b > a ? a = b, 1 : 0; }

void File() {
	freopen ("rudy.in", "r", stdin);
	freopen ("rudy.out", "w", stdout);
}

const int K = 105, Mod = 1e9 + 7;

ll n; int k;

template<int Maxn>
struct Matrix {

	int a[Maxn][Maxn];

	Matrix() { Set(a, 0); }

	inline void Unit(int len) {
		For (i, 1, len) a[i][i] = 1;
	}

	inline void Out() {
		For (i, 1, k + 1) For (j, 1, k + 1)
			printf ("%d%c", a[i][j], j == jend ? '\n' : ' ');
		putchar ('\n');
	}

};

typedef Matrix<K> Mat;

inline int id(int x, int step) {
	return x <= k ? ((x + step - 1) % k + 1) : x;
}

inline Mat Move(const Mat &Base, int step) {
	step %= k; Mat res;
	For (i, 1, k + 1) For (j, 1, k + 1)
		res.a[id(i, step)][id(j, step)] = Base.a[i][j];
	return res;
}

inline Mat operator * (const Mat &lhs, const Mat &rhs) {
	Mat res; int cur = k + 1;
	For (i, 1, cur) For(k, 1, cur) if (lhs.a[i][k]) For (j, 1, cur)
		res.a[i][j] = (res.a[i][j] + 1ll * lhs.a[i][k] * rhs.a[k][j]) % Mod;
	return res;
}

Mat A[K]; int ans[K];

int main () {

	cin >> n >> k;

	A[0].Unit(k + 1);
	For (i, 1, k + 1)
		A[0].a[1][i] = 1;

	vector<int> V;
	for (int len = 0; n; V.pb(n % k), n /= k) {
		Mat x = A[len]; A[++ len].Unit(k + 1);
		for (ll power = k, p = 0; power; power >>= 1) {
			if (power & 1) A[len] = A[len] * Move(x, (power ^ 1) << p);
			x = Move(x, 1 << p) * x; ++ p;
		}
	}

	int step = 0; ans[k + 1] = 1;

	Fordown (T, V.size() - 1, 0) {
		int cur = V[T];
		if (cur) {
			static int tmp[K];
			For (times, 0, cur - 1) {
				For (i, 1, k + 1) tmp[i] = ans[i], ans[i] = 0;
				Mat B = Move(A[T], times + step);
				For (i, 1, k + 1) For (j, 1, k + 1)
					ans[i] = (ans[i] + 1ll * tmp[j] * B.a[i][j]) % Mod;
			}
		}
		step += cur;
	}

	int res = 0;
	For (i, 1, k + 1) (res += ans[i]) %= Mod;
	printf ("%d\n", res);

	return 0;

}

